def is_protected(field): return field.lower() in PROTECTED_FIELD_NAMES
def needs_manual_confirm(path): return any(p in path.lower() for p in MANUAL_CONFIRM_PATTERNS)


def infer_type_name(v):
    if v is None: return "null"
    if isinstance(v, bool): return "bool"
    if isinstance(v, int): return "int"
    if isinstance(v, float): return "float"
    if isinstance(v, list): return "array"
    if isinstance(v, str): return "string"
    return "unknown"


