# STAGE 1: HAR -> endpoint_map (in-memory, no intermediate file)
# ============================================================================

def parse_body(post_data):
    if not post_data:
        return None, None
    mime = (post_data.get("mimeType") or "").split(";")[0].strip()
    text = post_data.get("text", "")
    if mime == "application/json":
        try:
            return json.loads(text), "json"
        except (json.JSONDecodeError, TypeError):
            return None, "json_unparsed"
    if mime == "application/x-www-form-urlencoded":
        params = post_data.get("params")
        data = {p["name"]: p.get("value", "") for p in params} if params else dict(parse_qsl(text))
        return data, "form"
    if mime == "multipart/form-data":
        return None, "multipart"
    return None, mime or "unknown"


def extract_response_baseline(resp):
    content = resp.get("content", {})
    mime = (content.get("mimeType") or "").split(";")[0].strip()
    text = content.get("text", "")
    shape = {}
    if mime == "application/json" and text:
        try:
            data = json.loads(text)
            if isinstance(data, dict):
                shape = {k: infer_type_name(v) for k, v in data.items()}
        except (json.JSONDecodeError, TypeError):
            pass
    return {"status": resp.get("status"), "body_shape": shape, "body_sample": text[:300]}


def parse_har(path, account_label):
    with open(path, "r", encoding="utf-8") as f:
        har = json.load(f)
    entries = har.get("log", {}).get("entries", [])
    parsed = []
    for e in entries:
        req, resp = e["request"], e["response"]
        method = req["method"]
        if method == "CONNECT":
            continue
        url = req["url"]
        pu = urlparse(url)
        body_data, body_type = parse_body(req.get("postData"))
        parsed.append({
            "account": account_label,
            "method": method,
            "host": pu.netloc,
            "path": pu.path,
            "url": url,
            "headers": {h["name"]: h["value"] for h in req.get("headers", []) if not h["name"].startswith(":")},
            "cookies": {c["name"]: c["value"] for c in req.get("cookies", [])},
            "query_params_full": {q["name"]: q.get("value") for q in req.get("queryString", [])},
            "body_json": body_data if body_type == "json" else None,
            "body_type": body_type,
            "baseline_response": extract_response_baseline(resp),
        })
    return parsed


def build_endpoint_map(entries):
    endpoint_map = {}
    for e in entries:
        key = f"{e['method']} {e['host']}{e['path']}"
        endpoint_map.setdefault(key, {"method": e["method"], "host": e["host"],
                                       "path": e["path"], "samples": []})
        endpoint_map[key]["samples"].append(e)
    return endpoint_map


def build_param_dictionary(endpoint_map):
    """Every field name + every value ever seen for it, across the whole HAR."""
    param_dict = {}
    for ep in endpoint_map.values():
        for sample in ep["samples"]:
            body = sample.get("body_json")
            if isinstance(body, dict):
                for k, v in body.items():
                    param_dict.setdefault(k, [])
                    if v not in param_dict[k]:
                        param_dict[k].append(v)
    return param_dict


