# STAGE 1.6: CSRF handling (embedded, single-use detection + auto-refresh)
# ============================================================================

class CsrfHandler:
    def __init__(self, session, token_url, token_extractor, field_name="csrf_token", inject_into="json_body"):
        self.session, self.token_url, self.token_extractor = session, token_url, token_extractor
        self.field_name, self.inject_into = field_name, inject_into
        self.mode, self._cached = None, None

    def fetch_token(self):
        resp = self.session.get(self.token_url)
        self._cached = self.token_extractor(resp)
        return self._cached

    def detect(self, probe_fn):
        token = self.fetch_token()
        first, second = probe_fn(token), probe_fn(token)
        if first.status_code < 400 and second.status_code < 400:
            self.mode = "reusable"
        elif first.status_code < 400:
            self.mode = "single_use"
        else:
            self.mode = "unknown"
        return self.mode

    def get_token(self):
        if self.mode == "single_use":
            return self.fetch_token()
        return self._cached or self.fetch_token()


