def gen_auth_drop(sample):
    out = []
    v = copy.deepcopy(sample); v["cookies"] = {}
    out.append(("auth_drop:no_cookies", v))
    v = copy.deepcopy(sample)
    for h in list(v["headers"]):
        if h.lower() in ("authorization", "x-csrf-token", "x-client-id"): del v["headers"][h]
    out.append(("auth_drop:no_auth_header", v))
    v = copy.deepcopy(sample)
    for h in list(v["headers"]):
        if h.lower() in ("authorization", "x-csrf-token", "x-client-id"): v["headers"][h] = "invalid_garbage_0000"
    out.append(("auth_drop:garbage_token", v))
    return out


def gen_type_confusion(sample):
    out = []
    body = sample.get("body_json")
    if not isinstance(body, dict): return out
    for field, value in body.items():
        if is_protected(field): continue
        for cand in TYPE_CONFUSION_VALUES.get(infer_type_name(value), TYPE_CONFUSION_VALUES["string"]):
            v = copy.deepcopy(sample); v["body_json"][field] = cand
            out.append((f"type_confusion:{field}={cand!r}", v))
    return out


def gen_missing_param(sample):
    out = []
    body = sample.get("body_json")
    if not isinstance(body, dict): return out
    for field in body:
        if is_protected(field): continue
        v = copy.deepcopy(sample); del v["body_json"][field]
        out.append((f"missing_param:{field}", v))
    return out


def gen_param_pollution(sample):
    out = []
    body = sample.get("body_json")
    if not isinstance(body, dict): return out
    for field, value in body.items():
        if is_protected(field): continue
        v = copy.deepcopy(sample)
        v["body_json"][field] = [value, value if not isinstance(value, str) else value + "_2"]
        out.append((f"param_pollution:{field}_as_array", v))
        alt = field.upper() if field != field.upper() else field.lower()
        if alt != field:
            v = copy.deepcopy(sample); v["body_json"][alt] = value
            out.append((f"param_pollution:{field}_case_dup", v))
    return out


def gen_mass_assignment(sample, param_dictionary):
    out = []
    body = sample.get("body_json")
    if not isinstance(body, dict): return out
    priority = ["role", "is_admin", "admin", "permission_level", "account_type",
                "tier", "is_verified", "verified", "email_verified", "kyc_status", "status"]
    candidates = [n for n in priority if n in param_dictionary]
    candidates += [n for n in param_dictionary if n not in candidates]
    for field in candidates[:15]:
        if field in body or is_protected(field): continue
        value = param_dictionary[field][0] if param_dictionary.get(field) else True
        v = copy.deepcopy(sample); v["body_json"][field] = value
        out.append((f"mass_assignment:{field}={value!r}", v))
    return out


def gen_idor_swap(sample_a, all_a_entries, session_b):
    """Cross-account: replay account A's request with account B's cookies/session."""
    out = []
    v = copy.deepcopy(sample_a)
    v["cookies"] = session_b.get("cookies", {})
    for h in ("authorization", "x-client-id"):
        for orig_h in list(v["headers"]):
            if orig_h.lower() == h and h in session_b.get("headers", {}):
                v["headers"][orig_h] = session_b["headers"][h]
    out.append(("idor_swap:account_a_request_with_b_session", v))
    return out


def method_matrix(variants):
    out = []
    for label, v in variants:
        for m in METHOD_MATRIX:
            vv = copy.deepcopy(v); vv["method"] = m
            out.append((f"{label}|method={m}", vv))
    return out


# ============================================================================
# structural diff
# ============================================================================

def structural_diff(baseline, resp):
    diff = {"status_changed": False, "keys_added": [], "keys_removed": [], "type_changes": {}}
    score = 0
    if baseline.get("status") != resp.status_code:
        diff["status_changed"] = f"{baseline.get('status')} -> {resp.status_code}"
        score += 1
    b_shape = baseline.get("body_shape", {}) or {}
    try:
        t_json = resp.json()
        t_shape = {k: infer_type_name(v) for k, v in t_json.items()} if isinstance(t_json, dict) else {}
    except (ValueError, AttributeError):
        t_shape = {}
    added, removed = set(t_shape) - set(b_shape), set(b_shape) - set(t_shape)
    if added: diff["keys_added"] = sorted(added); score += 1
    if removed: diff["keys_removed"] = sorted(removed); score += 1
    for k in set(b_shape) & set(t_shape):
        if b_shape[k] != t_shape[k]:
            diff["type_changes"][k] = f"{b_shape[k]} -> {t_shape[k]}"
    if diff["type_changes"]: score += 1
    diff["anomaly_score"] = score
    return diff


# ============================================================================
# ORCHESTRATION - the one entry point
# ============================================================================

def main():
    ap = argparse.ArgumentParser(description="HAR Logic Bug Engine - data embedded, single-file, single-run")
    ap.add_argument("--live", action="store_true", help="actually send requests (default: dry-run, shows plan only)")
    ap.add_argument("--rate-limit", type=float, default=2.0, help="seconds between live requests")
    ap.add_argument("--modules", nargs="*", default=None,
                     help="subset: auth_drop type_confusion missing_param param_pollution mass_assignment idor_swap")
    ap.add_argument("-o", "--findings-out", default="findings.json", help="where live findings get saved")
    args = ap.parse_args()

    raw_map = json.loads(EMBEDDED_ENDPOINT_MAP_JSON)
    endpoint_map = {k: {"method": v["method"], "host": v["host"], "path": v["path"],
                         "samples": [v["sample"]]} for k, v in raw_map.items()}
    param_dictionary = json.loads(EMBEDDED_PARAM_DICTIONARY_JSON)
    dual_account = False
    per_account = {"account_a": [ep["samples"][0] for ep in endpoint_map.values()]}
    print(f"[+] Using embedded capture data ({len(endpoint_map)} endpoints, baked in at build time)")

    all_modules = ["auth_drop", "type_confusion", "missing_param", "param_pollution", "mass_assignment"]
    if dual_account:
        all_modules.append("idor_swap")
    modules = args.modules or all_modules

    print(f"[+] {len(endpoint_map)} unique endpoints | param_dictionary: {len(param_dictionary)} fields | modules: {modules}")

    session = requests.Session()
    plan, findings, skipped = [], [], []

    for key, ep in endpoint_map.items():
        if ep["method"] not in ("POST", "PUT", "PATCH", "DELETE"):
            continue
        if needs_manual_confirm(ep["path"]):
            skipped.append(key); continue

        sample = ep["samples"][0]
        variants = []
        if "auth_drop" in modules: variants += gen_auth_drop(sample)
        if "type_confusion" in modules: variants += gen_type_confusion(sample)
        if "missing_param" in modules: variants += gen_missing_param(sample)
        if "param_pollution" in modules: variants += gen_param_pollution(sample)
        if "mass_assignment" in modules: variants += gen_mass_assignment(sample, param_dictionary)
        if "idor_swap" in modules and dual_account and sample["account"] == "account_a" and per_account.get("account_b"):
            b_ref = per_account["account_b"][0]
            variants += gen_idor_swap(sample, per_account["account_a"], b_ref)

        full_variants = method_matrix(variants)

        for label, v in full_variants:
            plan.append({"endpoint": key, "test": label, "method": v["method"], "url": v["url"]})
            if args.live:
                time.sleep(args.rate_limit)
                try:
                    resp = session.request(v["method"], v["url"], headers=v["headers"],
                                            cookies=v["cookies"], params=v.get("query_params_full"),
                                            json=v.get("body_json"), timeout=15)
                    diff = structural_diff(sample["baseline_response"], resp)
                    if diff["anomaly_score"] > 0:
                        findings.append({"endpoint": key, "test": label, "diff": diff, "status": resp.status_code})
                except requests.RequestException as e:
                    findings.append({"endpoint": key, "test": label, "error": str(e)})

    print(f"\n{'='*60}\nMode: {'LIVE' if args.live else 'DRY-RUN (nothing sent)'}")
    print(f"Total test cases: {len(plan)}")
    if skipped:
        print(f"Skipped (manual-confirm-only): {skipped}")

    if not args.live:
        print(f"\n--- first 20 of {len(plan)} planned test cases ---")
        for p in plan[:20]:
            print(f"  {p['method']:6s} {p['url'][:70]:70s} [{p['test']}]")
        print(f"\nRun again with --live to actually fire these.")
    else:
        print(f"\n--- {len(findings)} findings (anomaly_score > 0 or error) ---")
        with open(args.findings_out, "w") as f:
            json.dump(findings, f, indent=2, default=str)
        print(f"[+] saved to {args.findings_out}")
        for f_ in findings[:10]:
            print(json.dumps(f_, indent=2, default=str))


if __name__ == "__main__":
    main()
